insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-01', 'question', 'any', 'ru', 'Кто из нас мог бы вести собственное кулинарное шоу?', true, 'seed') on conflict (id) do nothing;
insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-02', 'question', 'any', 'ru', 'Кто из нас лучше всех рассказывает истории?', true, 'seed') on conflict (id) do nothing;
insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-03', 'question', 'any', 'ru', 'Кто из нас быстрее всех выучит новый язык, если переедет в другую страну?', true, 'seed') on conflict (id) do nothing;
insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-04', 'question', 'any', 'ru', 'Кто из нас продержался бы на необитаемом острове дольше всех?', true, 'seed') on conflict (id) do nothing;
insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-05', 'question', 'any', 'ru', 'Кто из нас лучше всех поддержит в трудную минуту?', true, 'seed') on conflict (id) do nothing;
insert into public.content_library (id, type, occasion, lang, text, approved, source) values ('seed-q-06', 'question', 'any', 'ru', 'Кто из нас чаще опаздывает — зато с самыми изобретательными оправданиями?', true, 'seed') on conflict (id) do nothing;
